ALTER TABLE group_expert_source_versions ADD COLUMN definition_digest TEXT NOT NULL DEFAULT '';
ALTER TABLE group_expert_source_versions ADD COLUMN invalid_reason TEXT NOT NULL DEFAULT '';
ALTER TABLE group_expert_scopes ADD COLUMN export_digest TEXT NOT NULL DEFAULT '';
ALTER TABLE group_expert_scopes ADD COLUMN export_json TEXT NOT NULL DEFAULT '[]';
CREATE TABLE group_expert_management_receipts (
    actor_id BIGINT NOT NULL,
    request_id TEXT NOT NULL,
    request_json TEXT NOT NULL,
    result_json TEXT NOT NULL,
    PRIMARY KEY(actor_id,request_id)
);
INSERT INTO group_expert_authorizations(domain_key,revision) SELECT 'user:'||id,1 FROM users WHERE true ON CONFLICT(domain_key) DO NOTHING;
CREATE FUNCTION octop_group_touch(domain text) RETURNS void LANGUAGE plpgsql AS $$ DECLARE v bigint; BEGIN INSERT INTO group_expert_authorizations(domain_key,revision) VALUES(domain,1) ON CONFLICT(domain_key) DO UPDATE SET revision=group_expert_authorizations.revision+1 RETURNING revision INTO v; INSERT INTO group_expert_outbox(operation_id,kind,target_id,payload,request_digest,created_at) VALUES('invalidate:'||domain||':'||v,'invalidate',domain,json_build_object('domain_key',domain,'revision',v)::text,domain||':'||v,CAST(EXTRACT(EPOCH FROM clock_timestamp()) AS BIGINT)); END; $$;
CREATE FUNCTION octop_group_user_change_0() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF true THEN PERFORM octop_group_touch('user:'||NEW.id); END IF; RETURN NULL; END; $$;
CREATE TRIGGER group_expert_users_insert AFTER INSERT ON users FOR EACH ROW EXECUTE FUNCTION octop_group_user_change_0();
CREATE FUNCTION octop_group_user_change_1() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.disabled IS DISTINCT FROM NEW.disabled OR OLD.role IS DISTINCT FROM NEW.role OR OLD.expert_access_mode IS DISTINCT FROM NEW.expert_access_mode OR OLD.expert_assignment_revision IS DISTINCT FROM NEW.expert_assignment_revision OR OLD.permissions IS DISTINCT FROM NEW.permissions THEN PERFORM octop_group_touch('user:'||NEW.id); END IF; RETURN NULL; END; $$;
CREATE TRIGGER group_expert_users_update AFTER UPDATE ON users FOR EACH ROW EXECUTE FUNCTION octop_group_user_change_1();
CREATE FUNCTION octop_group_user_change_2() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF true THEN PERFORM octop_group_touch('user:'||OLD.id); END IF; RETURN NULL; END; $$;
CREATE TRIGGER group_expert_users_delete AFTER DELETE ON users FOR EACH ROW EXECUTE FUNCTION octop_group_user_change_2();
CREATE FUNCTION octop_group_user_change_3() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.name='model_access' THEN PERFORM octop_group_touch('user:'||NEW.user_id); END IF; RETURN NULL; END; $$;
CREATE TRIGGER group_expert_user_policies_insert AFTER INSERT ON user_policies FOR EACH ROW EXECUTE FUNCTION octop_group_user_change_3();
CREATE FUNCTION octop_group_user_change_4() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.name='model_access' AND (OLD.enabled IS DISTINCT FROM NEW.enabled OR OLD.value IS DISTINCT FROM NEW.value) THEN PERFORM octop_group_touch('user:'||NEW.user_id); END IF; RETURN NULL; END; $$;
CREATE TRIGGER group_expert_user_policies_update AFTER UPDATE ON user_policies FOR EACH ROW EXECUTE FUNCTION octop_group_user_change_4();
