CREATE FUNCTION octop_group_department_insert() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE item record; BEGIN IF true THEN FOR item IN SELECT 'user:'||user_id AS domain_key FROM employee_resource_scopes WHERE scope_id=NEW.scope_id UNION SELECT 'scope:'||conversation_id FROM group_expert_scopes WHERE department_id=NEW.scope_id LOOP PERFORM octop_group_touch(item.domain_key); END LOOP; UPDATE group_expert_scopes SET revision=revision+1,export_digest='' WHERE department_id=NEW.scope_id; END IF; RETURN NULL; END; $$;
CREATE TRIGGER group_expert_department_insert AFTER INSERT ON department_resource_pools FOR EACH ROW EXECUTE FUNCTION octop_group_department_insert();
CREATE FUNCTION octop_group_department_update() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE item record; BEGIN IF OLD.expert_ids IS DISTINCT FROM NEW.expert_ids THEN FOR item IN SELECT 'user:'||user_id AS domain_key FROM employee_resource_scopes WHERE scope_id=NEW.scope_id UNION SELECT 'scope:'||conversation_id FROM group_expert_scopes WHERE department_id=NEW.scope_id LOOP PERFORM octop_group_touch(item.domain_key); END LOOP; UPDATE group_expert_scopes SET revision=revision+1,export_digest='' WHERE department_id=NEW.scope_id; END IF; RETURN NULL; END; $$;
