CREATE FUNCTION octop_group_department_delete() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE item record; BEGIN IF true THEN FOR item IN SELECT 'user:'||user_id AS domain_key FROM employee_resource_scopes WHERE scope_id=OLD.scope_id UNION SELECT 'scope:'||conversation_id FROM group_expert_scopes WHERE department_id=OLD.scope_id LOOP PERFORM octop_group_touch(item.domain_key); END LOOP; UPDATE group_expert_scopes SET revision=revision+1,export_digest='' WHERE department_id=OLD.scope_id; END IF; RETURN NULL; END; $$;
CREATE TRIGGER group_expert_department_delete AFTER DELETE ON department_resource_pools FOR EACH ROW EXECUTE FUNCTION octop_group_department_delete();
CREATE FUNCTION octop_group_source_identity_0() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE item record; BEGIN IF OLD.enabled IS DISTINCT FROM NEW.enabled OR OLD.user_id IS DISTINCT FROM NEW.user_id OR OLD.kind IS DISTINCT FROM NEW.kind THEN FOR item IN SELECT source_agent_id,source_row_id FROM group_expert_source_versions WHERE source_agent_id=NEW.agent_id AND source_row_id=NEW.id LOOP PERFORM octop_group_touch('source:'||item.source_agent_id||':'||item.source_row_id); END LOOP; UPDATE group_expert_source_versions SET revision=revision+1,invalid_reason='group_expert_configuration_changed' WHERE source_agent_id=NEW.agent_id AND source_row_id=NEW.id; END IF; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END; $$;
CREATE TRIGGER group_expert_source_identity_0 BEFORE UPDATE ON agents FOR EACH ROW EXECUTE FUNCTION octop_group_source_identity_0();
CREATE FUNCTION octop_group_source_identity_1() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE item record; BEGIN IF true THEN FOR item IN SELECT source_agent_id,source_row_id FROM group_expert_source_versions WHERE source_agent_id=OLD.agent_id AND source_row_id=OLD.id LOOP PERFORM octop_group_touch('source:'||item.source_agent_id||':'||item.source_row_id); END LOOP; UPDATE group_expert_source_versions SET revision=revision+1,invalid_reason='group_expert_configuration_changed' WHERE source_agent_id=OLD.agent_id AND source_row_id=OLD.id; END IF; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END; $$;
