CREATE FUNCTION octop_group_source_identity_2() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE item record; BEGIN IF OLD.source_user_id IS DISTINCT FROM NEW.source_user_id THEN FOR item IN SELECT source_agent_id,source_row_id FROM group_expert_source_versions WHERE true LOOP PERFORM octop_group_touch('source:'||item.source_agent_id||':'||item.source_row_id); END LOOP; UPDATE group_expert_source_versions SET revision=revision+1,invalid_reason='group_expert_configuration_changed' WHERE true; END IF; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END; $$;
CREATE TRIGGER group_expert_source_identity_2 BEFORE UPDATE ON expert_assignment_source FOR EACH ROW EXECUTE FUNCTION octop_group_source_identity_2();
CREATE FUNCTION octop_group_source_identity_3() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE item record; BEGIN IF OLD.disabled IS DISTINCT FROM NEW.disabled OR OLD.role IS DISTINCT FROM NEW.role THEN FOR item IN SELECT source_agent_id,source_row_id FROM group_expert_source_versions WHERE source_agent_id IN (SELECT agent_id FROM agents WHERE user_id=NEW.id) LOOP PERFORM octop_group_touch('source:'||item.source_agent_id||':'||item.source_row_id); END LOOP; UPDATE group_expert_source_versions SET revision=revision+1,invalid_reason='group_expert_configuration_changed' WHERE source_agent_id IN (SELECT agent_id FROM agents WHERE user_id=NEW.id); END IF; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END; $$;
